676	+func sameStrings(a, b []string) bool {
677	+	if len(a) != len(b) {
678	+		return false
679	+	}
680	+	seen := make(map[string]int, len(a))
681	+	for _, value := range a {
682	+		seen[value]++
683	+	}
684	+	for _, value := range b {
685	+		seen[value]--
686	+		if seen[value] < 0 {
687	+			return false
688	+		}
689	+	}
690	+	return true
691	+}
