1234	+	}
1235	+	changes := make(map[string]string)
1236	+	for _, line := range strings.Split(out, "\n") {
1237	+		if len(line) < 4 {
1238	+			continue
1239	+		}
1240	+		path := strings.TrimSpace(line[3:])
1241	+		if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
1242	+			path = path[arrow+4:]
1243	+		}
1244	+		if path != "" {
1245	+			changes[path] = line[:2]
1246	+		}
1247	+	}
1248	+	return changes, nil
1249	+}
