1390	+		var exitErr *exec.ExitError
1391	+		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1392	+			return candidate, nil // show-ref uses 1 for a missing ref
1393	+		}
1394	+		return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1395	+	}
1396	+	return "", errors.New("could not choose an unused configuration branch name")
1397	+}
1398

